#!/usr/bin/env python3
r"""Runs AnyPS5 hardware-oracle probes on the local AMD GPU and writes one compressed results file.

Usage:
    python anyps5_gpu_probes.py C:\path\to\AnyPS5            # run on the GPU
    python anyps5_gpu_probes.py C:\path\to\AnyPS5 --check    # only assemble the kernels (no GPU needed)

Linux: needs what docs/dev/HW_ORACLE.md lists (amdgpu driver, /dev/kfd access, ROCm HSA runtime, clang + ld.lld).
Windows: needs only the AMD Adrenalin driver (it installs amdhip64_*.dll). The kernels are the hardware oracle's,
prebuilt for RDNA 1, 2, 3 and 3.5 targets and launched through the HIP runtime instead of /dev/kfd.
"""
import base64
import gzip
import hashlib
import json
import os
import platform
import random
import struct
import subprocess
import sys
import tempfile
import time
from pathlib import Path

VERSION = 1
PREBUILT = ""

TITLE_MODE = dict(ieee=0, dx10_clamp=1, denorm32=0, denorm16=3, round32=0, round16=0, fp16_overflow=0)


def mode(**changes):
    result = dict(TITLE_MODE)
    result.update(changes)
    return result


def f16_bits_to_float(bits):
    return struct.unpack("<e", struct.pack("<H", bits))[0]


def float_to_f32_bits(value):
    return struct.unpack("<I", struct.pack("<f", value))[0]


SDWA_SELECTS = ["BYTE_0", "BYTE_1", "BYTE_2", "BYTE_3", "WORD_0", "WORD_1", "DWORD"]


def sdwa_body(byte):
    lines = []
    register = 10
    for select in SDWA_SELECTS:
        for extend in (False, True):
            source = "sext(v4)" if extend else "v4"
            lines.append(f"  v_cvt_f32_ubyte{byte}_sdwa v{register}, {source} dst_sel:DWORD dst_unused:UNUSED_PAD src0_sel:{select}")
            register += 1
    return "\n".join(lines) + "\n"


def sdwa_rows():
    values = [0x00000000, 0xffffffff, 0x80c1a2b3, 0x7f6e5d4c, 0x01020304, 0x80808080, 0x7f7f7f7f, 0xff00ff00,
              0x00ff00ff, 0x8000ffff, 0x00800080, 0xfedcba98, 0x12345678, 0xa5a5a5a5, 0x5a5a5a5a, 0x807f807f]
    values += [(index * 0x01010101) ^ (index << 4) for index in range(16)]
    generator = random.Random(1)
    values += [generator.getrandbits(32) for _ in range(32)]
    return [(value, 0, 0, 0) for value in values]


def pknorm_rows():
    return [(value, value ^ 0x8000, 0, 0) for value in range(0x10000)]


MULLIT_VALUES = [
    0x00000000, 0x80000000, 0x00000001, 0x80000001, 0x007fffff, 0x807fffff, 0x00400000, 0x00800000, 0x00800001,
    0x1f800000, 0x20000000, 0x1e3ce508, 0x3f000000, 0x3f800000, 0xbf800000, 0x40000000, 0x3f800001, 0x7f7fffff,
    0xff7fffff, 0xff7ffffe, 0x7f800000, 0xff800000, 0x7fc00000, 0x7f800001,
]


def mullit_rows():
    return [(a, b, c, 0) for a in MULLIT_VALUES for b in MULLIT_VALUES for c in MULLIT_VALUES]


def cvt_f16_f32_rows():
    halves = list(range(0x0000, 0x0420)) + list(range(0x3bf0, 0x3c10)) + list(range(0x7be0, 0x7c00))
    values = set()
    for half in halves:
        low = f16_bits_to_float(half)
        high = f16_bits_to_float(half + 1) if half + 1 < 0x7c00 else 65536.0
        for quarter in range(4):
            values.add(float_to_f32_bits(low + (high - low) * quarter / 4))
    for exponent in (-40, -30, -27, -26, -25):
        values.add(float_to_f32_bits(2.0 ** exponent))
        values.add(float_to_f32_bits(2.0 ** exponent * 1.5))
    values |= {0x00000001, 0x007fffff, 0x00800000, 0x7f7fffff, 0x7f800000, 0x7fc00000, 0x7f800001}
    values |= {float_to_f32_bits(value) for value in (65504.0, 65512.0, 65519.0, 65520.0, 65528.0, 65536.0, 1e5, 1e10)}
    values |= {value | 0x80000000 for value in list(values)}
    return [(value, 0, 0, 0) for value in sorted(values)]


def int16_rows():
    return [(value, 0, 0, 0) for value in range(0x10000)]


LDEXP_HALVES = [0x0001, 0x0002, 0x0003, 0x0155, 0x01ff, 0x0200, 0x0201, 0x02aa, 0x03ff, 0x0400, 0x0401, 0x0555,
                0x3555, 0x3bff, 0x3c00, 0x3c01, 0x4248, 0x7bfe, 0x7bff]


def ldexp_rows():
    exponents = list(range(-30, 31)) + [-1000, 1000, -32768, 32767]
    halves = LDEXP_HALVES + [half | 0x8000 for half in LDEXP_HALVES]
    return [(half, exponent & 0xffff, 0, 0) for half in halves for exponent in exponents]


def directed_modes():
    return [mode(round16=rounding, denorm16=denormals) for rounding in range(4) for denormals in range(4)]


PROBES = [
    {
        "name": "sdwa_cvt_f32_ubyte",
        "about": "SDWA src0_sel/sext on v_cvt_f32_ubyte0..3 (debt/shader.md: not measured)",
        "bodies": {f"ubyte{byte}": sdwa_body(byte) for byte in range(4)},
        "outs": 14,
        "rows": sdwa_rows,
        "modes": [mode()],
    },
    {
        "name": "cvt_pknorm_f16",
        "about": "v_cvt_pknorm_i16_f16 (v10) and v_cvt_pknorm_u16_f16 (v11) over every f16, high half negated",
        "bodies": {"pknorm": "  v_cvt_pknorm_i16_f16 v10, v4, v5\n  v_cvt_pknorm_u16_f16 v11, v4, v5\n"},
        "outs": 2,
        "rows": pknorm_rows,
        "modes": [mode(ieee=ieee, denorm16=denormals) for ieee in (0, 1) for denormals in range(4)]
                 + [mode(round16=rounding) for rounding in (1, 2, 3)],
    },
    {
        "name": "mullit_f32",
        "about": "v_mullit_f32 over 24^3 operand sets in every f32 denormal mode",
        "bodies": {"mullit": "  v_mullit_f32 v10, v4, v5, v6\n"},
        "outs": 1,
        "rows": mullit_rows,
        "modes": [mode(ieee=ieee, denorm32=denormals) for ieee in (0, 1) for denormals in range(4)],
    },
    {
        "name": "directed_cvt_f16_f32",
        "about": "v_cvt_f16_f32 (v10) and with clamp (v11) in every f16 round and denormal mode",
        "bodies": {"cvt": "  v_cvt_f16_f32 v10, v4\n  v_cvt_f16_f32_e64 v11, v4 clamp\n"},
        "outs": 2,
        "rows": cvt_f16_f32_rows,
        "modes": directed_modes(),
    },
    {
        "name": "directed_cvt_f16_int16",
        "about": "v_cvt_f16_u16 (v10), v_cvt_f16_i16 (v11) and v_cvt_f16_u16 clamp (v12) over every 16-bit value",
        "bodies": {"cvt": "  v_cvt_f16_u16 v10, v4\n  v_cvt_f16_i16 v11, v4\n  v_cvt_f16_u16_e64 v12, v4 clamp\n"},
        "outs": 3,
        "rows": int16_rows,
        "modes": directed_modes(),
    },
    {
        "name": "directed_ldexp_f16",
        "about": "v_ldexp_f16 (v10) and with clamp (v11) in every f16 round and denormal mode",
        "bodies": {"ldexp": "  v_ldexp_f16 v10, v4, v5\n  v_ldexp_f16 v11, v4, v5 clamp\n"},
        "outs": 2,
        "rows": ldexp_rows,
        "modes": directed_modes(),
    },
]


class HipBackend:
    """Runs hw_oracle kernels through the HIP runtime the AMD Windows driver installs."""

    HOST_TO_DEVICE = 1
    DEVICE_TO_HOST = 2

    def __init__(self, oracle):
        import ctypes
        self.ctypes = ctypes
        self.oracle = oracle
        self.hip = None
        names = ["amdhip64_7.dll", "amdhip64_6.dll", "amdhip64.dll"]
        folders = [Path(os.environ["HIP_PATH"]) / "bin"] if os.environ.get("HIP_PATH") else []
        errors = []
        for name in names:
            for candidate in [name] + [str(folder / name) for folder in folders]:
                try:
                    self.hip = ctypes.CDLL(candidate)
                    self.library = candidate
                    break
                except OSError as error:
                    errors.append(f"{candidate}: {error}")
            if self.hip:
                break
        if not self.hip:
            sys.exit("HIP runtime not found (amdhip64_*.dll). Install or update the AMD Adrenalin driver.\n" + "\n".join(errors))
        c = ctypes
        self.hip.hipGetErrorString.restype = c.c_char_p
        self.hip.hipGetErrorString.argtypes = [c.c_int]
        self.hip.hipModuleLoadData.argtypes = [c.POINTER(c.c_void_p), c.c_void_p]
        self.hip.hipModuleGetFunction.argtypes = [c.POINTER(c.c_void_p), c.c_void_p, c.c_char_p]
        self.hip.hipModuleUnload.argtypes = [c.c_void_p]
        self.hip.hipMalloc.argtypes = [c.POINTER(c.c_void_p), c.c_size_t]
        self.hip.hipFree.argtypes = [c.c_void_p]
        self.hip.hipMemcpy.argtypes = [c.c_void_p, c.c_void_p, c.c_size_t, c.c_int]
        self.hip.hipMemset.argtypes = [c.c_void_p, c.c_int, c.c_size_t]
        self.hip.hipModuleLaunchKernel.argtypes = [c.c_void_p, c.c_uint, c.c_uint, c.c_uint, c.c_uint, c.c_uint, c.c_uint,
                                                   c.c_uint, c.c_void_p, c.POINTER(c.c_void_p), c.POINTER(c.c_void_p)]
        self.check(self.hip.hipInit(0), "hipInit")
        self.check(self.hip.hipSetDevice(0), "hipSetDevice")
        os.environ["HW_ORACLE_TARGET"] = os.environ.get("HW_ORACLE_TARGET") or self.detect_target()

    @staticmethod
    def find_llvm():
        import shutil
        if shutil.which("clang") and shutil.which("ld.lld"):
            return
        for folder in (Path(os.environ.get("ProgramFiles", r"C:\Program Files")) / "LLVM" / "bin",
                       Path(os.environ["HIP_PATH"]) / "bin" if os.environ.get("HIP_PATH") else None):
            if folder and (folder / "clang.exe").exists() and (folder / "ld.lld.exe").exists():
                os.environ["PATH"] = str(folder) + os.pathsep + os.environ.get("PATH", "")
                return
        raise RuntimeError("no prebuilt kernel for this GPU and no clang.exe/ld.lld.exe with the AMDGPU target in PATH")

    def check(self, status, what):
        if status != 0:
            message = self.hip.hipGetErrorString(status)
            raise RuntimeError(f"{what} failed: {status} {message.decode() if message else ''}")

    def detect_target(self):
        import re
        buffer = self.ctypes.create_string_buffer(16384)
        for name in ("hipGetDevicePropertiesR0600", "hipGetDeviceProperties"):
            function = getattr(self.hip, name, None)
            if function is None:
                continue
            if function(buffer, 0) == 0:
                match = re.search(rb"gfx[0-9a-f]{3,4}", buffer.raw)
                if match:
                    return match.group(0).decode()
        sys.exit("could not read the GPU architecture; set HW_ORACLE_TARGET (for example gfx1030) and retry")

    def target(self):
        return os.environ["HW_ORACLE_TARGET"]

    def run(self, body, rows, code=None, extra=b"", wave64=False, coarse=False, *, lds=None, **modes):
        c = self.ctypes
        rows = [tuple(int(value) for value in row) for row in rows]
        wave = 64 if wave64 else 32
        padded = rows + [(0, 0, 0, 0)] * (-len(rows) % wave)
        per_dispatch = self.oracle.ROWS_PER_DISPATCH // 2 if wave64 else self.oracle.ROWS_PER_DISPATCH
        extra_args = {} if lds is None else {"lds": lds}
        out = []
        image = code
        if image is None:
            self.find_llvm()
            with tempfile.TemporaryDirectory() as directory:
                image = self.oracle.assemble(body, Path(directory), wave64, **modes, **extra_args).read_bytes()
        image_buffer = c.create_string_buffer(image, len(image))
        module = c.c_void_p()
        self.check(self.hip.hipModuleLoadData(c.byref(module), image_buffer), "hipModuleLoadData")
        try:
            function = c.c_void_p()
            self.check(self.hip.hipModuleGetFunction(c.byref(function), module, b"probe"), "hipModuleGetFunction")
            for start in range(0, len(padded), per_dispatch):
                chunk = padded[start:start + per_dispatch]
                data = b"".join(struct.pack("<4I", *row) for row in chunk) + extra
                in_size, out_size = len(data), len(chunk) * 64
                device_in, device_out = c.c_void_p(), c.c_void_p()
                self.check(self.hip.hipMalloc(c.byref(device_in), in_size), "hipMalloc")
                self.check(self.hip.hipMalloc(c.byref(device_out), out_size), "hipMalloc")
                try:
                    host_in = c.create_string_buffer(data, in_size)
                    self.check(self.hip.hipMemcpy(device_in, host_in, in_size, self.HOST_TO_DEVICE), "hipMemcpy")
                    self.check(self.hip.hipMemset(device_out, 0xee, out_size), "hipMemset")
                    params = (c.c_void_p * 2)(c.cast(c.pointer(device_in), c.c_void_p), c.cast(c.pointer(device_out), c.c_void_p))
                    self.check(self.hip.hipModuleLaunchKernel(function, 1, 1, 1, len(chunk), 1, 1, 0, None, params, None),
                               "hipModuleLaunchKernel")
                    self.check(self.hip.hipDeviceSynchronize(), "hipDeviceSynchronize")
                    host_out = c.create_string_buffer(out_size)
                    self.check(self.hip.hipMemcpy(host_out, device_out, out_size, self.DEVICE_TO_HOST), "hipMemcpy")
                finally:
                    self.hip.hipFree(device_in)
                    self.hip.hipFree(device_out)
                out += [struct.unpack_from("<16I", host_out.raw, lane * 64) for lane in range(len(chunk))]
        finally:
            self.hip.hipModuleUnload(module)
        return out[:len(rows)]


def load_backend(repo):
    sys.path.insert(0, str(repo / "tools" / "hw-oracle"))
    import hw_oracle
    if os.name == "nt" or os.environ.get("ANYPS5_PROBES_HIP"):
        backend = HipBackend(hw_oracle)
        hw_oracle.target = backend.target
        return hw_oracle, backend.run, backend.target, backend.library
    return hw_oracle, lambda body, rows, code=None, **settings: hw_oracle.run(body, rows, **settings), hw_oracle.target, "hsa (/dev/kfd)"


def kernel_key(target, probe, body, index):
    return f"{target}|{probe}|{body}|{index}"


def prebuilt_kernels():
    if not PREBUILT:
        return {}
    data = json.loads(gzip.decompress(base64.b64decode(PREBUILT)))
    return {key: base64.b64decode(value) for key, value in data.items()}


def build_prebuilt(oracle, targets):
    kernels = {}
    with tempfile.TemporaryDirectory() as directory:
        for target in targets:
            os.environ["HW_ORACLE_TARGET"] = target
            for probe in PROBES:
                for name, body in probe["bodies"].items():
                    for index, settings in enumerate(probe["modes"]):
                        try:
                            with open(os.devnull, "w") as quiet:
                                saved, sys.stderr = sys.stderr, quiet
                                try:
                                    code = oracle.assemble(body, Path(directory), False, **settings).read_bytes()
                                finally:
                                    sys.stderr = saved
                        except Exception:
                            continue
                        kernels[kernel_key(target, probe["name"], name, index)] = base64.b64encode(code).decode()
    return base64.b64encode(gzip.compress(json.dumps(kernels, sort_keys=True).encode(), 9)).decode(), len(kernels)


def system_info(target, runtime):
    info = {"platform": platform.platform(), "python": platform.python_version(), "runtime": runtime}
    try:
        info["target"] = target()
    except Exception as error:
        info["target_error"] = str(error)
    for path in ("/sys/module/amdgpu/version",):
        try:
            info[path] = Path(path).read_text().strip()
        except OSError:
            pass
    try:
        info["lspci"] = [line for line in subprocess.run(["lspci", "-nn"], capture_output=True, text=True).stdout.splitlines()
                         if "VGA" in line or "Display" in line or "3D" in line]
    except OSError:
        pass
    return info


def pack(results, outs):
    data = b"".join(struct.pack(f"<{outs}I", *row[:outs]) for row in results)
    return base64.b64encode(gzip.compress(data, 9)).decode()


def check(oracle):
    kernels = prebuilt_kernels()
    if kernels:
        targets = sorted({key.split("|")[0] for key in kernels})
        print(f"{len(kernels)} prebuilt kernels for {', '.join(targets)}")
        return 0
    os.environ.setdefault("HW_ORACLE_TARGET", "gfx1030")
    failures = 0
    with tempfile.TemporaryDirectory() as directory:
        for probe in PROBES:
            for name, body in probe["bodies"].items():
                try:
                    oracle.assemble(body, Path(directory), False, **probe["modes"][0])
                    print(f"ok      {probe['name']}/{name}")
                except Exception as error:
                    failures += 1
                    print(f"FAILED  {probe['name']}/{name}: {error}")
            print(f"        {len(probe['rows']())} rows x {len(probe['modes'])} modes")
    return 1 if failures else 0


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        return 2
    repo = Path(sys.argv[1]).resolve()
    if "--check" in sys.argv[2:] or "--build-prebuilt" in sys.argv[2:]:
        sys.path.insert(0, str(repo / "tools" / "hw-oracle"))
        import hw_oracle
        if "--build-prebuilt" in sys.argv[2:]:
            targets = sys.argv[sys.argv.index("--build-prebuilt") + 1].split(",")
            blob, count = build_prebuilt(hw_oracle, targets)
            source = Path(__file__).read_text()
            Path(__file__).write_text(source.replace('PREBUILT = ""\n', f'PREBUILT = "{blob}"\n', 1))
            print(f"embedded {count} kernels")
            return 0
        return check(hw_oracle)
    hw_oracle, run, target, runtime = load_backend(repo)
    output = Path(f"anyps5-gpu-probes-v{VERSION}.json.gz").resolve()
    report = {"version": VERSION, "script_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              "system": system_info(target, runtime), "probes": []}
    gpu = report["system"].get("target")
    print(f"GPU target: {gpu}", flush=True)
    kernels = prebuilt_kernels()
    for probe in PROBES:
        rows = probe["rows"]()
        for name, body in probe["bodies"].items():
            for index, settings in enumerate(probe["modes"]):
                started = time.time()
                entry = {"probe": probe["name"], "body_name": name, "body": body, "mode": settings,
                         "rows": len(rows), "outs": probe["outs"]}
                try:
                    code = kernels.get(kernel_key(gpu, probe["name"], name, index)) if kernels and runtime != "hsa (/dev/kfd)" else None
                    if kernels and runtime != "hsa (/dev/kfd)" and code is None:
                        raise RuntimeError(f"no prebuilt kernel for {gpu} (instruction not available on this GPU)")
                    results = run(body, rows, code=code, **settings)
                    entry["results"] = pack(results, probe["outs"])
                except Exception as error:
                    entry["error"] = f"{type(error).__name__}: {error}"
                report["probes"].append(entry)
                state = "error" if "error" in entry else "ok"
                print(f"{state:5} {probe['name']}/{name} {settings} {len(rows)} rows {time.time() - started:.1f}s", flush=True)
    with gzip.open(output, "wt") as handle:
        json.dump(report, handle)
    print(f"\nwrote {output} ({output.stat().st_size // 1024} KiB)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
